    """Shift all non-background cells down one row, dropping overflow."""
    if not grid:
        return []
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    out = [[bg] * w for _ in range(h)]
    for r in range(h - 1):
        for c, value in enumerate(grid[r]):
            if value != bg:
                out[r + 1][c] = value
    return out


